/** @param {NS} ns */
export async function main(ns) {
  const args = ns.args;
  const scriptName = "money.js";

  // Worker mode: perform single action
  if (args.length === 3) {
    const [action, target, threads] = args;
    if (action === "weaken") await ns.weaken(target, {threads});
    else if (action === "grow") await ns.grow(target, {threads});
    else if (action === "hack") await ns.hack(target, {threads});
    return;
  }

  // Coordinator mode
  const home = "home";
  const visited = new Set();
  let servers = [home];

  // Discover servers via scan
  function discover(srv) {
    if (visited.has(srv)) return;
    visited.add(srv);
    servers.push(srv);
    const scanned = ns.scan(srv);
    for (const next of scanned) discover(next);
  }

  discover(home);

  // Try to nuke servers
  const portTools = [
    "BruteSSH.exe",
    "FTPCrack.exe",
    "RelaySMTP.exe",
    "HTTPWorm.exe",
    "SQLInject.exe"
  ];

  for (const srv of servers) {
    if (ns.hasRootAccess(srv)) continue;
    let ports = 0;
    for (const tool of portTools) {
      if (ns.fileExists(tool, home)) {
        ports++;
        if (tool === "BruteSSH.exe") ns.brutessh(srv);
        else if (tool === "FTPCrack.exe") ns.ftpcrack(srv);
        else if (tool === "RelaySMTP.exe") ns.relaysmtp(srv);
        else if (tool === "HTTPWorm.exe") ns.httpworm(srv);
        else if (tool === "SQLInject.exe") ns.sqlinject(srv);
      }
    }
    if (ports >= ns.getServerNumPortsRequired(srv)) ns.nuke(srv);
  }

  const hackLvl = ns.getHackingLevel();
  let bestTarget = null;
  let bestMoney = 0;

  // Find best hackable target
  for (const srv of servers) {
    if (!ns.hasRootAccess(srv) || srv === home) continue;
    const req = ns.getServerRequiredHackingLevel(srv);
    const max = ns.getServerMaxMoney(srv);
    if (req <= hackLvl && max > 0 && max > bestMoney) {
      bestTarget = srv;
      bestMoney = max;
    }
  }

  if (!bestTarget) bestTarget = home;

  ns.tprint(`Target: ${bestTarget} (max: ${bestMoney})`);

  let lastLog = Date.now();

  while (true) {
    // Re-find best target every iteration
    let newBest = null;
    let newMoney = 0;
    for (const srv of servers) {
      if (!ns.hasRootAccess(srv)) continue;
      const req = ns.getServerRequiredHackingLevel(srv);
      const max = ns.getServerMaxMoney(srv);
      if (req <= hackLvl && max > 0 && max > newMoney) {
        newBest = srv;
        newMoney = max;
      }
    }
    if (newBest) bestTarget = newBest;

    // Get target info
    const sec = ns.getServerSecurityLevel(bestTarget);
    const minSec = ns.getServerMinSecurityLevel(bestTarget);
    const money = ns.getServerMoneyAvailable(bestTarget);
    const maxMoney = ns.getServerMaxMoney(bestTarget);

    // Dispatch work
    let actCount = 0;
    for (const srv of servers) {
      if (!ns.hasRootAccess(srv)) continue;
      let maxRam = ns.getServerMaxRam(srv);
      let usedRam = ns.getServerUsedRam(srv);
      if (srv === home) maxRam *= 0.8; // Reserve 20% on home
      let freeRam = maxRam - usedRam;
      if (freeRam <= 0.1) continue;

      const scriptRam = ns.getScriptRam(scriptName);
      const threads = Math.floor(freeRam / scriptRam);
      if (threads <= 0) continue;

      let action = "hack";
      if (sec > minSec + 5) action = "weaken";
      else if (money < maxMoney * 0.75) action = "grow";

      ns.exec(scriptName, srv, threads, action, bestTarget, threads);
      actCount++;
    }

    const now = Date.now();
    if (now - lastLog > 5000) {
      ns.tprint(`Target: ${bestTarget}, Sec: ${sec.toFixed(1)}, 
      Money: ${(money / 1e6).toFixed(1)}M/${(maxMoney / 1e6).toFixed(1)}M, 
      Actions: ${actCount}`);
      lastLog = now;
    }

    await ns.sleep(500);
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const args = ns.args;
  if (args.length === 2) {
    const mode = args[0];
    const target = args[1];
    if (mode === 'g') await ns.grow(target);
    else if (mode === 'w') await ns.weaken(target);
    else if (mode === 'h') await ns.hack(target);
    return;
  }

  let target = null;
  let maxMoney = 0;
  let scanQueue = ['home'];
  let visited = new Set(['home']);
  let loopCount = 0;
  let threadCount = 256;

  while (true) {
    if (!target) {
      while (scanQueue.length > 0) {
        const server = scanQueue.shift();
        const neighbors = ns.scan(server);
        for (const neighbor of neighbors) {
          if (!visited.has(neighbor)) {
            visited.add(neighbor);
            scanQueue.push(neighbor);
          }
        }
      }

      for (const server of visited) {
        if (ns.hasRootAccess(server)) {
          const reqLevel = ns.getServerRequiredHackingLevel(server);
          const maxM = ns.getServerMaxMoney(server);
          if (reqLevel <= ns.getHackingLevel() && maxM > maxMoney) {
            maxMoney = maxM;
            target = server;
          }
        }
      }

      if (!target) {
        ns.sleep(5000);
        scanQueue = ['home'];
        visited = new Set(['home']);
        continue;
      }
    }

    loopCount++;
    const available = ns.getServerMoneyAvailable(target);
    let mode = 'h';

    if (loopCount % 20 === 0) {
      mode = 'w';
    } else if (available < 0.6 * maxMoney) {
      mode = 'g';
    }

    let tries = threadCount;
    while (tries >= 1) {
      const pid = ns.exec('home-earner.js', 'home', tries, mode, target);
      if (pid !== 0) break;
      tries = Math.floor(tries / 2);
    }

    ns.sleep(100);
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const targets = ['n00dles', 'foodnstuff', 'sigma-cosmetics', 'joesguns'];
  let target = null;
  let cycle = 0;

  while (true) {
    // Pick target on first iteration or every 10 cycles
    if (!target || cycle % 10 === 0) {
      target = null;
      const level = ns.getHackingLevel();
      for (const t of targets) {
        if (ns.getServerRequiredHackingLevel(t) <= level && ns.getServerMaxMoney(t) > 0) {
          // Try to nuke if not already rooted
          try {
            if (!ns.hasRootAccess(t)) ns.nuke(t);
          } catch (e) {}
          if (ns.hasRootAccess(t)) {
            target = t;
            break;
          }
        }
      }
      if (!target) continue;
    }

    const maxMoney = ns.getServerMaxMoney(target);
    const available = ns.getServerMoneyAvailable(target);

    if (available < maxMoney * 0.5) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }

    if (++cycle % 10 === 0) {
      await ns.weaken(target);
    }
  }
}

